const trig = $('When Called').first().json;
const input = $input.first().json || {};
const validEbCode = trig.valid_eb_code !== false && /^EB-[A-Z0-9]{4,}$/.test(String(trig.property_public_id || '').trim().toUpperCase());
const resp = validEbCode ? input : {};
const easybroker_url = String(resp.public_url || '').trim();
const easybroker_url_valid = /^https:\/\/(?:www\.)?easybroker\.com\//i.test(easybroker_url);
const operations = Array.isArray(resp.operations) ? resp.operations : [];
const labels = { sale: 'Venta', rental: 'Renta', temporary_rental: 'Renta temporal' };
const operation_type = [...new Set(operations.map(op => labels[op.type] || op.type).filter(Boolean))].join(' / ') || trig.operation_type || '';
const property_price = [...new Set(operations.map(op => op.formatted_amount).filter(Boolean))].join(' / ') || trig.property_price || '';
const location = resp.location && typeof resp.location === 'object' ? resp.location : {};
const property_zone = location.name || location.full_name || trig.property_zone || '';
const property_title = resp.title || trig.property_title || '';
const property_public_id = String(resp.public_id || trig.property_public_id || '').trim().toUpperCase();
const tags = Array.isArray(resp.tags) ? resp.tags.map(tag => String(tag).trim()).filter(Boolean) : [];
const tag_count = tags.length;
const tag_cardinality_valid = tag_count === 1;
const resolution_ready = validEbCode && easybroker_url_valid && tag_cardinality_valid;
const observed_tag = tag_cardinality_valid ? tags[0] : null;
const tags_pg = tag_cardinality_valid
  ? '{"' + observed_tag.replace(/\\\\/g, '\\\\\\\\').replace(/"/g, '\\\\"') + '"}'
  : '{}';
const reason = !validEbCode
  ? 'property_public_id_required'
  : !easybroker_url_valid
    ? 'easybroker_public_url_missing'
    : !tag_cardinality_valid
      ? 'invalid_tag_count'
      : null;
return [{ json: { ...trig, property_public_id, property_title, operation_type, property_zone, property_price, easybroker_url: easybroker_url_valid ? easybroker_url : null, easybroker_url_valid, tags, tag_count, tag_cardinality_valid, resolution_ready, observed_tag, tags_pg, resolved: false, reason, failure_detail: reason, retryable: reason === 'easybroker_public_url_missing' } }];

const input = $input.first().json;
const code = String(input.property_public_id || '').trim().toUpperCase();
return [{ json: { ...input, property_public_id: code, valid_eb_code: /^EB-[A-Z0-9]{4,}$/.test(code) } }];
